const pagePaths={Overview:'/overview','Agent Chat':'/agent-chat','Expert Library':'/experts','Component Library':'/components',Projects:'/administration',Deployments:'/deployments','Project Files':'/project-files','Platform Settings':'/platform-settings','User Control':'/users',Activity:'/activity'};
const pathPages=Object.fromEntries(Object.entries(pagePaths).map(([page,path])=>[path.slice(1),page]));
const routeValue=value=>{try{return decodeURIComponent(value||'')}catch{return String(value||'')}};
function applyLocationRoute(pathname=location.pathname){
  const segments=String(pathname||'/').split('/').filter(Boolean).map(routeValue),root=segments[0]||'overview';
  state.selected=null;state.selectedComponent=null;state.componentEditor=false;state.skillAssistant=null;state.whatsappMonitor=null;
  if(root==='login'){state.page='Overview';return true}
  if(root==='whatsapp-monitor'){state.page='WhatsApp Monitor';state.whatsappMonitorGroupId=segments[1]||null;return true}
  const page=pathPages[root];if(!page){state.page='Overview';return false}state.page=page;
  if(page==='Expert Library'&&segments[1])state.selected=segments[1];
  if(page==='Component Library'){
    if(segments[1]==='new')state.componentEditor='new';
    else if(segments[1]==='type'&&segments[2])state.componentTab=segments[2];
    else if(segments[1]){state.selectedComponent=segments[1];if(segments[2]==='edit')state.componentEditor=segments[1]}
  }
  if(page==='Projects'&&['projects','organizations','database'].includes(segments[1]))state.projectAdminTab=segments[1];
  if(page==='Project Files'){
    if(['library','templates','connectors'].includes(segments[1]))state.projectFilesTab=segments[1];
    if(segments[2])state.projectFilesProjectId=segments[2];
  }
  if(page==='Platform Settings'){
    if(['system','models','database','hermes','hermes-middleware','visual','translations'].includes(segments[1]))state.platformSettingsTab=segments[1];
    if(segments[1]==='models'&&segments[2])state.modelSettingsTab=segments[2];
  }
  if(page==='Agent Chat'&&segments[1]){state.chatProjectId=segments[1];state.chatDeploymentId=segments[2]||null}
  return true;
}
function currentRoutePath(){
  if(state.page==='WhatsApp Monitor')return state.whatsappMonitorGroupId?`/whatsapp-monitor/${encodeURIComponent(state.whatsappMonitorGroupId)}`:'/deployments';
  if(state.page==='Expert Library'&&state.selected)return `/experts/${encodeURIComponent(state.selected)}`;
  if(state.page==='Component Library'){
    if(state.componentEditor==='new')return '/components/new';
    if(state.componentEditor)return `/components/${encodeURIComponent(state.componentEditor)}/edit`;
    if(state.selectedComponent)return `/components/${encodeURIComponent(state.selectedComponent)}`;
    if(state.componentTab&&state.componentTab!=='all')return `/components/type/${encodeURIComponent(state.componentTab)}`;
  }
  if(state.page==='Projects')return `/administration/${state.projectAdminTab||'projects'}`;
  if(state.page==='Project Files')return `/project-files/${state.projectFilesTab||'library'}${state.projectFilesProjectId?`/${encodeURIComponent(state.projectFilesProjectId)}`:''}`;
  if(state.page==='Platform Settings')return `/platform-settings/${state.platformSettingsTab||'models'}${state.platformSettingsTab==='models'&&state.modelSettingsTab?`/${encodeURIComponent(state.modelSettingsTab)}`:''}`;
  if(state.page==='Agent Chat'&&state.chatProjectId)return `/agent-chat/${encodeURIComponent(state.chatProjectId)}${state.chatDeploymentId?`/${encodeURIComponent(state.chatDeploymentId)}`:''}`;
  return pagePaths[state.page]||'/overview';
}
