const appearance=()=>state.data.settings||state.platformAppearance||{};
const platformLanguage=()=>['en','zh-Hant','zh-Hans'].includes(state.session?.user?.preferredLanguage)?state.session.user.preferredLanguage:state.loginLanguage;
const tr=value=>appearance().translationOverrides?.[platformLanguage()]?.[value]||translations[platformLanguage()]?.[value]||value;
const platformName=()=>String(appearance().platformName||'Agent Platform');
