function chatAttachmentMarkup() { return state.chatFiles.length?state.chatFiles.map((file,index)=>`<span class="chat-file-chip">${escape(file.name)} <button type="button" data-remove-chat-file="${index}" aria-label="Remove ${escape(file.name)}">×</button></span>`).join(''):''; }
function artifactQaMarkup(artifact){const qa=artifact?.reportValidation;if(!qa)return '';const label=qa.status==='passed'?'QA passed':qa.status==='passed-with-warnings'?'QA passed with warnings':'QA failed',issues=[...(qa.errors||[]).map(value=>({tone:'failed',label:'Error',value})),...(qa.warnings||[]).map(value=>({tone:'warning',label:'Warning',value}))],tableTotal=Number(qa.tableTargetCount||qa.tableMappings?.length||0),tableMapped=Number(qa.mappedTableCount||0),coverage=`${Number(qa.mappedFieldCount||0)}/${Number(qa.activeFieldCount||0)} fields${tableTotal?` · ${tableMapped}/${tableTotal} tables`:''}`;return `<details class="artifact-qa ${qa.status==='passed-with-warnings'?'has-warning':qa.status==='failed'?'has-error':''}"><summary><span class="status-pill ${qa.status==='passed'?'':qa.status==='passed-with-warnings'?'simulated':'failed'}">${escape(label)} · ${coverage}</span>${issues.length?`<span class="artifact-qa-count">${issues.length} issue${issues.length===1?'':'s'}</span>`:''}</summary>${issues.length?`<ul>${issues.map(issue=>`<li class="${issue.tone}"><strong>${issue.label}:</strong> ${escape(issue.value)}</li>`).join('')}</ul><p class="small">Review the selected Document Template definition or supply the missing evidence, then regenerate the report.</p>`:`<p class="small">All active fields${tableTotal?' and configured table rules':''} passed report validation.</p>`}</details>`}
function chatMessageMarkup(message,agent) { const artifact=message.artifact,artifactDetail=artifact?.templateName?`${Number.isFinite(artifact.size)?formatBytes(artifact.size):'Generated file'} · Template: ${artifact.templateName}`:Number.isFinite(artifact?.size)?formatBytes(artifact.size):'Generated file';return `<article class="chat-message ${message.role==='user'?'from-user':'from-agent'}"><div class="message-meta">${message.role==='user'?'You':escape(agent.expert.name)} · ${new Date(message.createdAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}${message.outputFormat?` · ${escape(message.outputFormat.toUpperCase())} requested`:''}</div>${message.attachments?.length?`<div class="message-files">${message.attachments.map(file=>`<span>📎 ${escape(file.name)}</span>`).join('')}</div>`:''}<p>${escape(message.content)}</p>${artifact?`<div class="generated-artifact"><span class="artifact-format">${escape((artifact.generatedFormat||'file').toUpperCase())}</span><div><strong>${escape(artifact.name)}</strong><small>${escape(artifactDetail)}</small>${artifactQaMarkup(artifact)}</div><a class="ghost" href="/api/documents/${artifact.id}/view" target="_blank">Open</a><a class="primary" href="/api/documents/${artifact.id}/download">Download</a></div>`:''}${message.role==='assistant'?`<span class="simulation-note">${message.simulated?'Simulated reply':`Live · ${escape(message.model||state.data.settings.modelName)}`}</span>`:''}</article>`; }
function agentChatPage() {
  const access=chatProjects(),project=activeChatProject(),agent=activeChatAgent(),live=Boolean(state.data.settings?.modelConnected);
  if(!access.length)return shell(`${header('Agent Chat','Talk directly with the specialists assigned to your protected projects.')}<section class="form-card chat-empty"><div class="section-kicker">No project access</div><h2>No project conversations are available</h2><p class="subtle">Ask an administrator to grant project access, agent access and the Talk to project agents permission.</p></section>`);
  const agentList=project?.agents||[],messages=state.chatMessages||[],projectTemplates=(state.data.documents||[]).filter(document=>document.projectId===project?.id&&document.documentType==='template');
  const conversation=agent?`<section class="chat-panel"><header class="chat-panel-head"><img class="chat-head-avatar" src="${expertPortrait(agent.expert)}" alt="Cartoon portrait of ${escape(agent.expert.name)}"><div><div class="section-kicker">${escape(project.name)}</div><h2>${escape(agent.expert.name)}</h2><p>${escape(agent.expert.specialty)} · ${escape(agent.deploymentName)}</p></div><span class="status-pill ${agent.state==='running'?'':'simulated'}">${escape(agent.state)}</span></header><div class="chat-feed" id="chat-feed" aria-live="polite">${messages.length?messages.map(message=>chatMessageMarkup(message,agent)).join(''):`<div class="chat-welcome"><div class="section-kicker">Unified agent context</div><h3>Continue with ${escape(agent.expert.name)}</h3><p>This is the same deployed agent used in its bound WhatsApp groups. Recent attributed group discussion and shared Project Files are available here automatically.</p></div>`}</div><form class="chat-composer" id="chat-form"><div class="chat-attachment-queue" id="chat-attachment-queue">${chatAttachmentMarkup()}</div><div class="chat-input-row"><label class="chat-attach-button" title="Attach files"><input id="chat-file-input" type="file" multiple>＋<span>Attach</span></label><label class="sr-only" for="chat-message">Message ${escape(agent.expert.name)}</label><textarea id="chat-message" name="content" maxlength="2000" placeholder="Ask ${escape(agent.expert.name)} about ${escape(project.name)}…"></textarea></div><div><span class="small">${live?`Live · ${escape(state.data.settings.modelName)} · unified Agent Chat and WhatsApp context`:'No live model configured · replies will use the local simulation.'}<br>Enter to send · Shift+Enter for a new line · drop or paste files</span><label class="chat-output">Create<select id="chat-output"><option value="">Chat reply</option><option value="docx">DOCX document</option><option value="pdf">PDF document</option><option value="image">Image</option></select></label><label class="chat-output" id="chat-template-field" hidden>Template<select id="chat-template"><option value="">Automatic selection</option>${projectTemplates.map(template=>`<option value="${template.id}" data-format="${template.templateFormat}">${escape(template.name)}</option>`).join('')}</select></label><button class="primary" id="chat-send">Send message</button></div></form></section>`:`<section class="chat-panel chat-empty"><div><div class="section-kicker">No assigned agent</div><h2>No project agent is available here</h2><p class="subtle">An administrator can grant an agent and a deployment manager can put that expert into this project.</p></div></section>`;
  return shell(`${header('Agent Chat','Choose a project and talk to a specific deployed specialist inside that project boundary.')}<div class="chat-layout"><aside class="chat-roster"><label class="field">Project<select id="chat-project">${access.map(item=>`<option value="${item.id}" ${item.id===project?.id?'selected':''}>${escape(item.name)}</option>`).join('')}</select></label><div class="chat-roster-label">Available agents</div><div class="chat-agent-list">${agentList.length?agentList.map(item=>`<button class="chat-agent ${item.deploymentId===agent?.deploymentId?'active':''}" data-chat-agent="${item.deploymentId}"><img src="${expertPortrait(item.expert)}" alt=""><span><strong>${escape(item.expert.name)}</strong><small>${escape(item.expert.specialty)}</small></span><i class="agent-state ${item.state==='running'?'online':''}" aria-label="${escape(item.state)}"></i></button>`).join(''):'<p class="small">No permitted deployed agents in this project.</p>'}</div><div class="notice compact-notice"><strong>Access boundary</strong><br>Only agents and projects granted in User Control appear here.</div></aside>${conversation}</div>`);
}
function drawChatAttachments() { const queue=document.querySelector('#chat-attachment-queue');if(queue)queue.innerHTML=chatAttachmentMarkup(); }
function acceptChatFiles(incoming) { const unique=[],seen=new Set();for(const file of [...state.chatFiles,...Array.from(incoming)]){const key=`${file.name}:${file.size}:${file.lastModified}`;if(!seen.has(key)){seen.add(key);unique.push(file)}}state.chatFiles=unique;drawChatAttachments(); }
function chatProgressMarkup() { const stages=['Uploading attachments','Reading permitted project files',`Contacting ${escape(state.data.settings?.modelName||'default model')}`,'Preparing the specialist reply'],current=state.chatStatus?.stage??0;return `<article class="agent-thinking" id="agent-thinking"><span class="thinking-pulse"></span><div><strong>${escape(activeChatAgent()?.expert?.name||'Agent')} is working</strong><ol>${stages.map((stage,index)=>`<li class="${index<current?'done':index===current?'active':''}">${index<current?'✓':'•'} ${stage}</li>`).join('')}</ol></div></article>`; }
function showChatProgress(stage) { state.chatStatus={stage};const feed=document.querySelector('#chat-feed');if(!feed)return;feed.querySelector('#agent-thinking')?.remove();feed.insertAdjacentHTML('beforeend',chatProgressMarkup());feed.scrollTop=feed.scrollHeight; }
async function selectChat(projectId,deploymentId=null) { state.chatProjectId=projectId;const project=chatProjects().find(item=>item.id===projectId);state.chatDeploymentId=deploymentId||project?.agents[0]?.deploymentId||null;state.chatFiles=[];state.chatStatus=null;state.chatMessages=state.chatDeploymentId?await api(`/api/projects/${state.chatProjectId}/deployments/${state.chatDeploymentId}/messages`):[];render(); }
function bindAgentChat() {
  document.querySelectorAll('#chat-template option[value]').forEach(option=>{const template=(state.data.documents||[]).find(item=>item.id===option.value);if(template)option.textContent=`${templateCallName(template)}${template.isDefault?' — default':''}`});
  document.querySelector('#chat-project')?.addEventListener('change',event=>selectChat(event.target.value).catch(error=>toast(error.message)));
  document.querySelectorAll('[data-chat-agent]').forEach(button=>button.addEventListener('click',()=>selectChat(state.chatProjectId,button.dataset.chatAgent).catch(error=>toast(error.message))));
  const form=document.querySelector('#chat-form'),input=document.querySelector('#chat-file-input'),message=document.querySelector('#chat-message'),output=document.querySelector('#chat-output');
  if(output){const templateField=document.querySelector('#chat-template-field'),templateSelect=document.querySelector('#chat-template');const showTemplate=()=>{const format=output.value,documentOutput=['docx','pdf'].includes(format);if(templateField)templateField.hidden=!documentOutput;if(!templateSelect)return;const current=templateSelect.value;for(const option of templateSelect.options){if(!option.value){option.hidden=false;continue}const sourceFormat=option.dataset.format;option.hidden=!(sourceFormat===format||(format==='pdf'&&sourceFormat==='docx'))}if(current&&templateSelect.selectedOptions[0]?.hidden)templateSelect.value='';templateSelect.disabled=!documentOutput};output.addEventListener('change',showTemplate);showTemplate()}
  input?.addEventListener('change',()=>{acceptChatFiles(input.files);input.value=''});
  form?.addEventListener('dragover',event=>{event.preventDefault();form.classList.add('dragging')});
  form?.addEventListener('dragleave',()=>form.classList.remove('dragging'));
  form?.addEventListener('drop',event=>{event.preventDefault();form.classList.remove('dragging');acceptChatFiles(event.dataTransfer.files)});
  form?.addEventListener('click',event=>{const button=event.target.closest('[data-remove-chat-file]');if(!button)return;state.chatFiles.splice(Number(button.dataset.removeChatFile),1);drawChatAttachments()});
  message?.addEventListener('paste',event=>{const files=Array.from(event.clipboardData?.files||[]);if(files.length){event.preventDefault();acceptChatFiles(files)}});
  message?.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();form?.requestSubmit()}});
  form?.addEventListener('submit',async event=>{event.preventDefault();const content=message.value.trim(),files=[...state.chatFiles],outputFormat=document.querySelector('#chat-output')?.value||'',templateId=document.querySelector('#chat-template')?.value||'';if(!content&&!files.length)return toast('Enter a message or attach a file.');const optimisticId=`pending-${Date.now()}`,optimisticContent=content||`Please review the attached file${files.length===1?'':'s'}: ${files.map(file=>file.name).join(', ')}.`,optimistic={id:optimisticId,role:'user',content:optimisticContent,outputFormat:outputFormat||null,attachments:files.map(file=>({name:file.name,size:file.size,mimeType:file.type})),createdAt:new Date().toISOString(),pending:true};state.chatFiles=[];state.chatMessages.push(optimistic);state.chatStatus={stage:files.length?0:1};render();showChatProgress(files.length?0:1);const timers=[];try{let uploaded=[];if(files.length)uploaded=await uploadFiles(files,{projectId:state.chatProjectId,deploymentId:state.chatDeploymentId,visibility:'private',source:'chat'});showChatProgress(1);timers.push(setTimeout(()=>showChatProgress(2),650));timers.push(setTimeout(()=>showChatProgress(3),3200));const result=await api(`/api/projects/${state.chatProjectId}/deployments/${state.chatDeploymentId}/messages`,{method:'POST',body:{content,outputFormat,templateId,attachmentIds:uploaded.map(file=>file.id)}});timers.forEach(clearTimeout);state.chatStatus=null;state.chatMessages=state.chatMessages.filter(item=>item.id!==optimisticId);state.chatMessages.push(...result.messages);render()}catch(error){timers.forEach(clearTimeout);state.chatStatus=null;const pending=state.chatMessages.find(item=>item.id===optimisticId);if(pending)pending.pending=false;render();toast(error.message)}});
  const feed=document.querySelector('#chat-feed');if(feed){if(state.chatStatus)feed.insertAdjacentHTML('beforeend',chatProgressMarkup());feed.scrollTop=feed.scrollHeight;}
}
function profile(e) { const comps = (e.draft.componentRefs || []).map(ref => state.data.components.find(c => c.id === ref.componentId)).filter(Boolean); const adopted = deployments().filter(d => d.expertId === e.id); return shell(`${header('Expert profile','Review this capable team member before putting them to work.', `<button class="quiet" data-action="edit-expert" data-id="${e.id}">Edit draft</button> <button class="primary" data-deploy-expert="${e.id}">Put this expert to work</button>`)}<div class="detail-grid"><div><section class="profile-hero"><div class="profile-title"><div class="section-kicker">${escape(e.specialty)}</div><h1>${escape(e.name)}</h1><p class="subtle">${escape(e.description)}</p><div class="tags">${e.tags.map(tag).join('')}</div></div><span class="status-pill">${escape(e.status)}</span></section><section class="section form-card"><div class="section-kicker">Capability kit</div><h2>What this member brings</h2><div class="information">${comps.map(c => `<div class="info-row"><strong>${escape(c.name)}</strong><span class="subtle">${escape(c.description)}</span></div>`).join('') || '<p class="subtle">Build this expert’s capability kit in the draft editor.</p>'}</div></section><section class="section form-card"><div class="section-kicker">Adoption</div><h2>Where this member is helping</h2>${adopted.length ? `<div class="list">${adopted.map(d => `<div class="row"><div><h3>${escape(d.name)}</h3><p>${escape(projects().find(p => p.id === d.projectId)?.name || 'Organization scope')} · Edition ${escape(d.pinnedEdition || '')}</p></div><span class="status-pill">${escape(d.state)}</span></div>`).join('')}</div>` : '<p class="subtle">Not assigned yet. Put this expert to work when a project is ready.</p>'}</section></div><aside><section class="form-card"><div class="section-kicker">Release record</div><h2>Edition history</h2><div class="list">${e.versions.length ? e.versions.slice().reverse().map(v => `<div class="row"><div><h3>Edition ${v.version}</h3><p>Published ${new Date(v.publishedAt).toLocaleDateString()}</p></div><span class="status-pill">Pinned</span></div>`).join('') : '<p class="subtle">This expert is still a draft. Publish after review.</p>'}</div></section><section class="form-card section"><div class="section-kicker">Draft revision ${e.draft.revision}</div><h2>Draft controls</h2><p class="subtle">Published editions stay unchanged for active deployments.</p><div class="card-actions"><button class="primary" data-publish="${e.id}">Publish edition</button><button class="danger" data-archive="${e.id}">Archive</button></div></section></aside></div>`); }
function wizard(e = null) { const draft = state.expertDraft || (e ? { name:e.name, specialty:e.specialty, description:e.draft.description || e.description, tags:(e.draft.tags || []).join(', '), instructions:e.draft.instructions || '', refs:e.draft.componentRefs?.map(x => x.componentId) || [] } : { name:'',specialty:'',description:'',tags:'',instructions:'',refs:[] }); state.expertDraft = draft; const skills=(state.data.components||[]).filter(component=>component.type==='skill'&&component.status!=='archived'),supporting=(state.data.components||[]).filter(component=>component.type!=='skill'&&component.status!=='archived');const choices=list=>list.map(c => `<button type="button" class="choice capability-choice ${draft.refs.includes(c.id) ? 'selected' : ''}" data-choice="${c.id}" aria-pressed="${draft.refs.includes(c.id)}"><span>${draft.refs.includes(c.id)?'✓':'＋'}</span>${escape(c.name)} <small>(${escape(c.versions?.at(-1)?`Edition ${c.versions.at(-1).version}`:'Draft')})</small></button>`).join(''); return shell(`${header(e ? `Edit ${escape(e.name)}’s draft` : 'Create a new expert','Assign reusable skills explicitly, then publish an edition for deployments to use.')}<section class="form-card"><div class="wizard-steps"><span class="wizard-step active">1. Profile</span><span class="wizard-step active">2. Assigned skills</span><span class="wizard-step active">3. Operating rhythm</span><span class="wizard-step active">4. Review</span></div><form id="expert-form" class="form-grid"><label class="field">Team member name<input name="name" value="${escape(draft.name)}" required></label><label class="field">Specialist role / outcome<input name="specialty" value="${escape(draft.specialty)}" placeholder="e.g. HSE / safety lead" required></label><label class="field wide">Plain-language description<textarea name="description" required>${escape(draft.description)}</textarea></label><label class="field wide">Optional tags<input name="tags" value="${escape(draft.tags)}" placeholder="e.g. safety, construction starter"></label><section class="wide capability-assignment"><div class="section-kicker">Assigned skills · ${draft.refs.filter(id=>skills.some(skill=>skill.id===id)).length} selected</div><h2>Grant task capabilities to ${escape(draft.name||'this agent')}</h2><p class="subtle">Select the skills this agent may apply in Agent Chat and WhatsApp. The runtime chooses only relevant assigned skills for each request.</p><div class="choices capability-choices">${choices(skills)||'<p class="empty">Create a detailed skill in Component Library first.</p>'}</div></section><details class="wide supporting-components"><summary>Supporting capability components</summary><p class="small">Personas, tools, permissions, schedules and health checks can also be attached to the expert edition.</p><div class="choices">${choices(supporting)}</div></details><label class="field wide">Working instructions and escalation posture<textarea name="instructions" placeholder="Use approved project context, state uncertainty and escalate urgent risks.">${escape(draft.instructions)}</textarea></label><div class="wide"><div class="notice"><strong>Activation:</strong> saving updates the draft. Publish a new expert edition, then upgrade an existing deployment so Sally’s live runtime receives the new skill assignment.</div></div><div class="wide"><button class="primary" type="submit">${e ? 'Save skill assignments' : 'Save expert draft'}</button> <button class="ghost" type="button" data-page="Expert Library">Cancel</button></div></form></section>`); }
const componentTypeOptions={skill:'Skill',persona:'Working style / persona',tool:'Tool',permission_profile:'Permission profile',folder_blueprint:'Project folder blueprint',knowledge_pack:'Knowledge pack',cron_job:'Scheduled job',schedule:'Schedule',heartbeat:'Health check'};
function componentTypeSelect(current='skill'){return Object.entries(componentTypeOptions).map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join('')}
function skillEditorBase(component=null) { const content=component?.draft?.content||{},value=field=>escape(content[field]||''),editing=Boolean(component),currentType=component?.type||'skill';return shell(`${header(editing?`Edit ${escape(component.name)} draft`:'Create component',editing?`Update the editable ${escape(componentTypeOptions[currentType]||currentType.replaceAll('_',' '))} contract without changing published editions.`:'Define a reusable construction capability with an explicit type, inputs, workflow, evidence rules and safe outputs.')}<section class="form-card skill-editor"><form id="skill-form" class="form-grid" data-component-id="${component?.id||''}"><input type="hidden" name="revision" value="${component?.draft?.revision||1}"><div class="wide section-kicker">01 · Identity and activation</div><label class="field">Component type<select name="type" required>${componentTypeSelect(currentType)}</select><small>Choose how the runtime applies and enforces this component.</small></label><label class="field">Component name<input name="name" value="${escape(component?.name||'')}" placeholder="e.g. Temporary works inspection" required></label><label class="field wide">Short description<input name="description" value="${escape(component?.description||'')}" placeholder="What outcome does this component provide?" required></label><label class="field wide">Objective<textarea name="objective" placeholder="State the result this component must produce and for whom." required>${value('objective')}</textarea></label><label class="field wide">When to use / trigger phrases<textarea name="triggers" placeholder="Use when the user asks about…&#10;Trigger examples: inspect scaffold, review permit, prepare RFI">${value('triggers')}</textarea></label><div class="wide section-kicker">02 · Operating contract</div><label class="field wide">Required inputs<textarea name="inputs" placeholder="List required project facts, documents, dates, drawings or approvals.">${value('inputs')}</textarea></label><label class="field wide">Step-by-step instructions<textarea name="instructions" rows="9" placeholder="1. Confirm scope and current revision.&#10;2. Search approved project evidence.&#10;3. Check…&#10;4. Produce…" required>${value('instructions')}</textarea></label><label class="field wide">Evidence and source rules<textarea name="evidence" placeholder="Which sources are allowed? How should the component cite evidence and state uncertainty?">${value('evidence')}</textarea></label><label class="field wide">Output contract<textarea name="output" placeholder="Define the required sections, tables, file type, decision or action list." required>${value('output')}</textarea></label><div class="wide section-kicker">03 · Safety and evaluation</div><label class="field wide">Guardrails and prohibited actions<textarea name="guardrails" placeholder="What must the component never assume, disclose or action?" required>${value('guardrails')}</textarea></label><label class="field wide">Escalation rules<textarea name="escalation" placeholder="When must the component stop, warn, or refer to a responsible professional?">${value('escalation')}</textarea></label><label class="field wide">Test prompt<textarea name="exampleInput" placeholder="Example request used to verify this component.">${value('exampleInput')}</textarea></label><label class="field wide">Expected good response<textarea name="exampleOutput" placeholder="Describe the essential qualities and facts expected in the response.">${value('exampleOutput')}</textarea></label><label class="field wide">Tags<input name="tags" value="${escape((component?.tags||[]).join(', '))}" placeholder="inspection, safety, temporary works"></label><div class="wide skill-editor-actions"><button class="primary">${editing?'Save draft changes':'Save component draft'}</button><button class="ghost" type="button" data-action="cancel-skill">Cancel</button></div></form></section>`); }
function skillAssistantMarkup(){const assistant=state.skillAssistant||{open:false,messages:[],suggestion:null,busy:false},messages=assistant.messages.length?assistant.messages:[{role:'assistant',content:'Describe the skill outcome, users and evidence available. I can draft the complete operating contract, improve one section, or review the current form.'}];return `<div class="skill-assistant-scrim ${assistant.open?'open':''}" data-action="close-skill-assistant"></div><aside class="skill-assistant-drawer ${assistant.open?'open':''}" aria-hidden="${!assistant.open}" aria-label="Skill Draft Assistant"><header><div><div class="section-kicker">AI authoring support</div><h2>Skill Draft Assistant</h2><p>Chat first. Nothing changes until you apply the proposed draft.</p></div><button class="icon-button" type="button" data-action="close-skill-assistant" aria-label="Close assistant"><i class="ph ph-x"></i></button></header><div class="skill-assistant-quick"><button type="button" data-skill-assistant-prompt="Draft a complete skill from the purpose and notes already entered in the form.">Draft complete skill</button><button type="button" data-skill-assistant-prompt="Review and strengthen the evidence rules, guardrails and escalation criteria.">Strengthen safety</button><button type="button" data-skill-assistant-prompt="Make the instructions specific, sequential and testable while preserving the intended outcome.">Improve workflow</button></div><div class="skill-assistant-messages" aria-live="polite">${messages.map(item=>`<article class="${item.role==='user'?'from-author':'from-assistant'}"><strong>${item.role==='user'?'You':'Assistant'}</strong><p>${escape(item.content)}</p></article>`).join('')}${assistant.busy?'<article class="from-assistant assistant-thinking"><strong>Assistant</strong><p>Reviewing the draft and preparing an update…</p></article>':''}</div><div class="skill-assistant-proposal ${assistant.suggestion?'visible':''}"><div><strong>Updated draft ready</strong><span>Review it in the form before saving.</span></div><button class="primary" type="button" data-action="apply-skill-assistant" ${assistant.suggestion?'':'disabled'}>Apply to form</button></div><form class="skill-assistant-composer" id="skill-assistant-form"><textarea name="message" rows="3" maxlength="2000" placeholder="e.g. Create a lifting-plan review skill for an HSE lead" ${assistant.busy?'disabled':''}></textarea><div><span>Enter to send · Shift+Enter for a new line</span><button class="primary" ${assistant.busy?'disabled':''}>Send</button></div></form></aside>`}
function skillEditor(component=null){const page=skillEditorBase(component),launch='<button class="ghost skill-assistant-launch" type="button" data-action="open-skill-assistant"><i class="ph ph-chats-teardrop"></i> Draft with assistant</button>';return page.replace('<div class="headline-action"></div>',`<div class="headline-action">${launch}</div>`).replace('</main></div>',`${skillAssistantMarkup()}</main></div>`)}
