function runtimeInspectorMarkup(){const payload=state.runtimeInspector;if(!payload)return '';if(payload.loading)return `<div class="runtime-inspector-scrim"><aside class="runtime-inspector-drawer"><header><div><div class="section-kicker">Deployment runtime</div><h2>Loading component contract…</h2></div><button class="icon-button" data-close-runtime aria-label="Close">×</button></header><div class="runtime-inspector-loading">Compiling the pinned expert edition and reading its execution history…</div></aside></div>`;const runtime=payload.runtime||{},manifest=payload.manifest||{},permissions=runtime.permissions||{},components=runtime.components||[],runs=payload.runs||[],typeLabel=value=>String(value||'component').replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase()),formatTime=value=>value?new Date(value).toLocaleString():'Not run yet';const componentRows=components.map(component=>{const runnable=(runtime.schedules||[]).find(item=>item.componentId===component.componentId)||(runtime.heartbeats||[]).find(item=>item.componentId===component.componentId);return `<article class="runtime-component-card"><div><span class="element-kind">${escape(typeLabel(component.type))}</span><strong>${escape(component.name)}</strong><small>Edition ${escape(component.version||'pinned')} · ${escape(component.description||'')}</small></div>${runnable?`<div><span class="status-pill ${runnable.status==='failed'?'simulated':''}">${escape(runnable.status||'scheduled')}</span><small>Next ${formatTime(runnable.nextRunAt)}</small><button class="quiet" data-run-runtime="${escape(component.componentId)}">Run now</button></div>`:'<span class="runtime-enforced">Enforced</span>'}</article>`}).join('');return `<div class="runtime-inspector-scrim"><aside class="runtime-inspector-drawer"><header><div><div class="section-kicker">Pinned execution contract</div><h2>${escape(payload.deployment?.name||'Runtime details')}</h2><p>Edition ${escape(payload.deployment?.edition||'')} · manifest r${escape(manifest.revision||payload.deployment?.manifestRevision||'—')} · ${escape((manifest.manifestHash||payload.deployment?.manifestHash||'').slice(0,16))}</p></div><button class="icon-button" data-close-runtime aria-label="Close">×</button></header><div class="runtime-policy-grid"><div><span>Project evidence</span><strong>${permissions.readProjectContext?'Allowed':'Denied'}</strong></div><div><span>Drafts and documents</span><strong>${permissions.prepareDrafts?'Allowed':'Denied'}</strong></div><div><span>Risk escalation</span><strong>${permissions.escalateRisks?'Enabled':'Not assigned'}</strong></div><div><span>Execution</span><strong>${escape(manifest.execution?.mode||payload.deployment?.execution?.executionMode||'direct')}</strong></div></div><div class="notice compact-notice"><strong>Effective instructions</strong><br><pre class="manifest-preview">${escape(manifest.instructions?.effective||'No compiled instructions available.')}</pre></div><div class="runtime-inspector-body"><section><div class="runtime-section-heading"><h3>Assigned components</h3><span>${components.length} pinned</span></div><div class="runtime-component-list">${componentRows||'<p class="empty">No components are pinned to this edition.</p>'}</div></section><section><div class="runtime-section-heading"><h3>Recent execution</h3><span>${runs.length} records</span></div><div class="runtime-run-list">${runs.map(run=>`<article><i class="${run.status==='failed'||run.status==='attention'?'warning':''}"></i><div><strong>${escape(run.componentName||typeLabel(run.type))}</strong><p>${escape(typeLabel(run.type))} · ${escape(run.status)} · ${formatTime(run.createdAt)}${run.manifestRevision?` · manifest r${escape(run.manifestRevision)}`:''}</p></div></article>`).join('')||'<p class="empty">Execution records appear after the agent handles a request or a scheduled component runs.</p>'}</div></section></div><footer><span>Components are pinned to this expert edition and shared by Agent Chat and WhatsApp.</span><button class="quiet" data-close-runtime>Close</button></footer></aside></div>`}
