    const bot=data.bot||{},health=bot.lastError?'Unhealthy':bot.runtimeId?'Ready':'Not provisioned',runtimeLabel=bot.runtimeKind==='local-cli'?'Real NousResearch Hermes CLI execution':bot.runtimeKind==='reference'?'Reference adapter only — no Hermes execution':bot.runtimeKind||'Unknown runtime';
    section.innerHTML=`<div class="runtime-section-heading"><h3>Hermes runtime</h3><span>${escape(health)}</span></div><p class="small">${escape(runtimeLabel)}</p><div class="runtime-policy-grid"><div><span>Execution scope</span><strong>${escape(bot.executionScopeId||bot.providerBotId||'Not provisioned')}</strong></div><div><span>Runtime ID</span><strong>${escape(bot.runtimeId||'Not assigned')}</strong></div><div><span>Runtime version</span><strong>${escape(bot.runtimeVersion||'unknown')}</strong></div><div><span>State</span><strong>${escape(bot.status||'unknown')}</strong></div></div><div class="detail-actions"><button type="button" class="ghost" data-hermes-lifecycle="health">Health check</button><button type="button" class="ghost" data-hermes-lifecycle="restart">Restart runtime scope</button><button type="button" class="quiet" data-hermes-lifecycle="stop">Stop deployment scope</button></div>`;
