    body.prepend(terminal);
    const terminalOutput=terminal.querySelector('[data-hermes-terminal-output]'),terminalForm=terminal.querySelector('[data-hermes-terminal-form]'),terminalInput=terminalForm.elements.command,history=[];let historyIndex=0;
    const terminalLine=(className,prefix,value)=>{const line=document.createElement('p');line.className=className;const label=document.createElement('strong');label.textContent=prefix;line.append(label,document.createTextNode(value));terminalOutput.append(line);terminalOutput.scrollTop=terminalOutput.scrollHeight;return line};
    const executeTerminal=async(command,confirmCommand=false)=>{terminalInput.disabled=true;terminalForm.querySelector('button').disabled=true;terminalLine('hermes-terminal-command','$ hermes ',command);try{const result=await api(`/api/deployments/${encodeURIComponent(deploymentId)}/hermes-console/terminal`,{method:'POST',body:{command,mode:'chat',confirm:confirmCommand}});if(result.aliasUsed&&result.command&&result.command!==command)terminalLine('hermes-terminal-system','↳ normalized to: $ hermes ',result.command);terminalLine('hermes-terminal-output','',result.stdout||result.stderr||'(Command completed without output.)');if(result.stderr)terminalLine('hermes-terminal-error','stderr: ',result.stderr)}catch(error){if(error.requiresConfirmation&&confirm(`Run the state-changing Hermes CLI command “hermes ${command}”? This action is audited.`))return executeTerminal(command,true);terminalLine('hermes-terminal-error','error: ',error.message)}finally{terminalInput.disabled=false;terminalForm.querySelector('button').disabled=false;terminalInput.focus()}};
    terminalForm.addEventListener('submit',event=>{event.preventDefault();const value=terminalInput.value.trim().replace(/^hermes\s+/i,'');if(!value)return;history.push(value);historyIndex=history.length;terminalInput.value='';executeTerminal(value)});
    terminalInput.addEventListener('keydown',event=>{if(!['ArrowUp','ArrowDown'].includes(event.key)||!history.length)return;event.preventDefault();historyIndex=Math.max(0,Math.min(history.length,event.key==='ArrowUp'?historyIndex-1:historyIndex+1));terminalInput.value=history[historyIndex]||''});
