    const section=document.createElement('section');section.dataset.hermesDirectChat='true';
    section.innerHTML='<div class="runtime-section-heading"><div><h3>Hermes agent conversation</h3><p>Natural-language request through this deployment’s Hermes execution pipeline.</p></div><span>Agent execution · not CLI</span></div><div class="hermes-console-chat-messages" data-hermes-chat-messages><p class="empty">Use this for an agent conversation. Use the terminal above for Hermes CLI commands.</p></div><form class="hermes-console-chat-form" data-hermes-chat-form><textarea name="content" rows="3" placeholder="Message the Hermes agent…" required></textarea><button class="primary">Send to agent</button></form>';
    terminal.after(section);
