        const text=typeof result?.content==='string'&&result.content.trim()?result.content:typeof result?.reply==='string'&&result.reply.trim()?result.reply:typeof result?.message==='string'&&result.message.trim()?result.message:'Hermes returned no content. Check the execution trace for details.';
