async function loadWhatsAppMonitor() {
  if(!state.whatsappMonitorGroupId||state.page!=='WhatsApp Monitor')return;
  if(state.whatsappCoach)return;
  try { state.whatsappMonitor=await api(`/api/groups/${state.whatsappMonitorGroupId}/monitor`); if(state.page==='WhatsApp Monitor')render(); }
  catch(error){toast(error.message);state.whatsappMonitor={error:error.message,group:{name:'Unavailable'},project:{projectNo:'—'},deployment:{name:'Unavailable',state:'unknown'},expert:{name:'Agent'},model:{configured:false},bridge:{connected:false,error:error.message},messages:[],checkedAt:new Date().toISOString()};if(state.page==='WhatsApp Monitor')render()}
  clearTimeout(state.whatsappMonitorTimer);if(state.page==='WhatsApp Monitor')state.whatsappMonitorTimer=setTimeout(loadWhatsAppMonitor,2500);
}
