function projectFileType(document) {
  const extension=String(document.generatedFormat||document.name?.split('.').pop()||'file').toLowerCase();
  if(extension==='pdf')return {extension:'PDF',label:'PDF document',icon:'file-pdf'};
  if(['doc','docx'].includes(extension))return {extension:extension.toUpperCase(),label:'Word document',icon:'file-doc'};
  if(['png','jpg','jpeg','gif','webp','bmp'].includes(extension))return {extension:extension.toUpperCase(),label:'Image',icon:'file-image'};
  if(['txt','md','csv'].includes(extension))return {extension:extension.toUpperCase(),label:'Text document',icon:'file-text'};
  return {extension:extension.toUpperCase(),label:'File',icon:'file'};
}
