function modelCapabilityCard(capability){const model=state.data.settings?.models?.[capability]||{},meta=legacyModelCapabilityMeta[capability],legacy=capability==='chat',modelName=model.modelName||(legacy?state.data.settings?.modelName:'')||'',serviceUrl=model.serviceUrl||(legacy?state.data.settings?.serviceUrl:'')||'',connected=Boolean(model.connected||(legacy&&state.data.settings?.modelConnected));return `<article class="model-profile ${connected?'connected':''}"><header><div><div class="section-kicker">${escape(capability)}</div><h2>${meta[0]}</h2><p>${meta[1]}</p></div><span class="status-pill ${connected?'':'simulated'}">${connected?'Configured':'Not configured'}</span></header><form class="form model-profile-form" data-model-capability="${capability}"><label class="field">Model name<input name="modelName" value="${escape(modelName)}" placeholder="Provider model ID" required></label><label class="field">Service URL<input name="serviceUrl" value="${escape(serviceUrl)}" placeholder="https://provider.example/v1" required></label><label class="field">API key<input name="apiKey" type="password" autocomplete="new-password" placeholder="${model.hasApiKey?'Saved — leave blank to keep':'Enter API key'}"></label><label class="field">Timeout (seconds)<input name="modelTimeoutSeconds" type="number" min="30" max="600" value="${escape(model.modelTimeoutSeconds||state.data.settings?.modelTimeoutSeconds||180)}" required></label><label class="checkline"><input name="enabled" type="checkbox" ${model.enabled===false?'':'checked'}><span>Enable this capability route</span></label><div class="model-profile-actions"><button class="primary">Save</button><button type="button" class="ghost" data-test-model="${capability}">Test connection</button></div></form></article>`}
function connectorPage() { const guide=connectorGuides[state.connectorService||'Microsoft 365 email'];return shell(`${header('Model & Connectors','Route each AI capability to the provider and model best suited to the task. API keys are encrypted independently.')}<section class="model-registry"><div class="model-registry-intro"><div><div class="section-kicker">Capability routing</div><h2>Model registry</h2><p class="subtle">The same virtual agent can use different services for reasoning, voice, vision, generation and retrieval.</p></div><span class="tag">${Object.keys(legacyModelCapabilityMeta).filter(key=>state.data.settings?.models?.[key]?.connected||(key==='chat'&&state.data.settings?.modelConnected)).length} configured</span></div><div class="model-profile-grid">${Object.keys(legacyModelCapabilityMeta).map(modelCapabilityCard).join('')}</div></section><div class="split section"><section class="form-card"><h2>Connect a project service</h2><form id="connector-form" class="form"><label class="field">Project<select name="projectId" required><option value="">Choose project</option>${projects().map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select></label><label class="field">Service<select name="service" id="connector-service">${Object.keys(connectorGuides).map(s=>`<option ${s===state.connectorService?'selected':''}>${s}</option>`).join('')}</select></label><div class="notice"><strong>What you need:</strong> ${guide[0]}<br><span class="small">${guide[1]} <a href="${guide[2]}" target="_blank">Official instructions ↗</a></span></div><label class="field">${guide[0]}<input name="credential" type="password" required></label><button class="primary">Save encrypted connection</button></form></section><section class="form-card"><h2>Saved project connections</h2><p class="subtle">Credentials are redacted and never displayed here.</p><div id="connector-list" class="list"><p class="empty">Choose a project and save a service connection to see it here.</p></div></section></div>`); }
