    drawer.querySelector('[data-element-prop="kind"]')?.addEventListener('change',()=>{commitEditor();const element=definition.find(item=>item.id===selectedId);if(element?.kind==='table'&&(!Array.isArray(element.columns)||!element.columns.length)){element.columns=[newColumn()];dirty=true}renderWorkspace()});
    drawer.querySelector('[data-add-template-column]')?.addEventListener('click',()=>{commitEditor();const element=definition.find(item=>item.id===selectedId);if(!element||element.kind!=='table')return;element.columns=[...(element.columns||[]),newColumn()];element.origin='manual';element.reviewedAt=null;element.reviewedBy=null;dirty=true;renderWorkspace()});
    drawer.querySelectorAll('[data-remove-template-column]').forEach(button=>button.addEventListener('click',()=>{commitEditor();const element=definition.find(item=>item.id===selectedId);if(!element||element.kind!=='table')return;element.columns=(element.columns||[]).filter(column=>column.id!==button.dataset.removeTemplateColumn);element.origin='manual';element.reviewedAt=null;element.reviewedBy=null;dirty=true;renderWorkspace()}));
    drawer.querySelectorAll('[data-region-prop],[data-region-coordinate]').forEach(input=>input.addEventListener('change',()=>{commitEditor();dirty=true;renderWorkspace()}));
    drawer.querySelector('#template-element-form')?.addEventListener('input',event=>{const element=definition.find(item=>item.id===event.currentTarget.dataset.elementId);if(element){element.origin='manual';if(element.reviewedAt){element.reviewedAt=null;element.reviewedBy=null}}dirty=true;drawer.querySelector('.template-definition-summary>p').textContent='Unsaved changes';drawer.querySelector('footer>div>span').textContent='Changes are not saved yet.'});
    const ask=async message=>{commitEditor();const selectedElement=definition.find(element=>element.id===selectedId);if(!selectedElement||!message.trim())return;aiBusy=true;lastAssistant={elementId:selectedId,question:message,reply:'Reviewing this element and its evidence rules…'};renderWorkspace();try{const result=await api(`/api/documents/${template.id}/template-assistant`,{method:'POST',body:{message,elementId:selectedId,element:selectedElement,definition}});const index=definition.findIndex(element=>element.id===selectedId);if(index>=0)definition[index]={...definition[index],...result.element,origin:'manual',included:definition[index].included!==false,reviewedAt:null,reviewedBy:null};dirty=true;lastAssistant={elementId:selectedId,question:message,reply:result.reply}}catch(error){lastAssistant={elementId:selectedId,question:message,reply:error.message}}finally{aiBusy=false;renderWorkspace()}};
    drawer.querySelectorAll('[data-ai-prompt]').forEach(button=>button.addEventListener('click',()=>ask(button.dataset.aiPrompt)));
