function submit(url,message,method='POST'){return async e=>{e.preventDefault();try{await api(url,{method,body:formData(e.currentTarget)});await reload(message)}catch(err){toast(err.message)}}}
function login(mode='signin',resetToken='',notice=''){const signin=`<form id="login-form" class="form"><label class="field">Email<input name="email" type="email" placeholder="you@company.com" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password"></label><button class="primary">Enter workspace <span aria-hidden="true">→</span></button><button class="login-link" type="button" data-login-view="request">Forgot password?</button></form>`;const requestReset=`<form id="reset-request-form" class="form"><div class="login-recovery-note"><strong>Reset from this computer</strong><br>For security, password recovery can only be started on the computer hosting the Agent Platform.</div><label class="field">Account email<input name="email" type="email" placeholder="you@company.com" required autocomplete="email"></label><button class="primary">Continue to reset</button><button class="login-link" type="button" data-login-view="signin">← Back to sign in</button></form>`;const completeReset=`<form id="reset-complete-form" class="form"><input name="token" type="hidden" value="${escape(resetToken)}"><div class="login-recovery-note"><strong>Create a new password</strong><br>This one-time reset expires in 15 minutes and signs out existing sessions.</div><label class="field">New password<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label class="field">Confirm new password<input name="confirmPassword" type="password" minlength="8" required autocomplete="new-password"></label><p class="small">Use at least 8 characters with uppercase, lowercase and a number.</p><button class="primary">Reset password</button><button class="login-link" type="button" data-login-view="request">Start again</button></form>`;const heading=mode==='signin'?'Welcome to the<br>project desk.':'Recover your<br>account.';const intro=mode==='signin'?'Bring the right construction expert into the right project conversation—with every workspace protected by project boundaries.':'Securely replace a forgotten password without exposing the password already stored by the platform.';app.innerHTML=`<main class="login"><section class="login-copy"><div class="login-wordmark">Varadise</div><p class="eyebrow">Construction AI Agent Platform</p><h1>${heading}</h1><p class="subtle">${intro}</p>${mode==='request'?requestReset:mode==='complete'?completeReset:signin}<p class="login-trust">Protected project homes</p><p id="login-error" class="small login-feedback">${escape(notice)}</p></section><aside class="login-photo"><img src="/assets/construction-project-desk.png" alt="Tower crane above a construction project with plans in the foreground"><p>Every decision, document and expert stays in the right place.</p></aside></main>`;document.querySelectorAll('[data-login-view]').forEach(button=>button.addEventListener('click',()=>login(button.dataset.loginView)));document.querySelector('#login-form')?.addEventListener('submit',async event=>{event.preventDefault();try{await api('/api/auth/login',{method:'POST',body:formData(event.currentTarget)});state.page='Overview';await refresh();render()}catch(error){document.querySelector('#login-error').textContent=error.message}});document.querySelector('#reset-request-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const result=await api('/api/auth/password-reset/request',{method:'POST',body:formData(event.currentTarget)});login('complete',result.token)}catch(error){document.querySelector('#login-error').textContent=error.message}});document.querySelector('#reset-complete-form')?.addEventListener('submit',async event=>{event.preventDefault();const data=formData(event.currentTarget);if(data.password!==data.confirmPassword){document.querySelector('#login-error').textContent='The new passwords do not match.';return}try{await api('/api/auth/password-reset/complete',{method:'POST',body:{token:data.token,password:data.password}});login('signin','','Password reset. Sign in with your new password.')}catch(error){document.querySelector('#login-error').textContent=error.message}})}
async function start(){try{state.platformAppearance=await api('/api/platform')}catch{state.platformAppearance={platformName:'Agent Platform',platformLanguage:'en',platformLogoDataUrl:''}}try{state.session=await api('/api/auth/session');await refresh();render()}catch{state.session=null;login()}}start();
function permissionFields(user={}) { const administrator=user.role==='administrator';return `<fieldset class="access-fieldset"><legend>Permissions</legend><div class="permission-grid">${permissionOptions.map(([id,label])=>`<label class="checkline"><input type="checkbox" name="permissions" value="${id}" ${administrator||user.permissions?.includes(id)?'checked':''} ${administrator?'disabled':''}><span>${label}</span></label>`).join('')}</div>${administrator?'<p class="small">Administrators always retain every permission.</p>':''}</fieldset>`; }
function organizationAccessFields(user={}) { const administrator=user.role==='administrator';return `<fieldset class="access-fieldset"><legend>Organization access</legend>${administrator?'<div class="notice compact-notice">All current and future organizations and projects</div>':'<p class="small">Selecting an organization grants access to all current and future projects in it.</p>'}${orgs().length?`<div class="permission-grid organization-permissions">${orgs().map(organization=>`<label class="checkline"><input type="checkbox" name="organizationIds" value="${organization.id}" ${administrator||user.organizationIds?.includes(organization.id)?'checked':''} ${administrator?'disabled':''}><span>${escape(organization.name)} <small>${projects().filter(project=>project.organizationId===organization.id).length} projects</small></span></label>`).join('')}</div>`:'<p class="small">No organizations are available yet.</p>'}</fieldset>`; }
function projectAccessFields(user={}) { const administrator=user.role==='administrator',firstSelectedProject=projects().find(project=>user.projectIds?.includes(project.id)),initialOrganizationId=firstSelectedProject?.organizationId||orgs().find(organization=>projects().some(project=>project.organizationId===organization.id))?.id||'';return `<fieldset class="access-fieldset"><legend>Direct project access</legend><p class="small">Choose an organization, then grant additional projects outside the user’s organization-level access.</p>${administrator?'<div class="notice compact-notice">All current and future projects</div>':''}${projects().length?`<div class="project-access-toolbar"><label class="field">Filter projects by organization<select data-project-organization-filter>${orgs().map(organization=>`<option value="${organization.id}" ${organization.id===initialOrganizationId?'selected':''}>${escape(organization.name)} · ${projects().filter(project=>project.organizationId===organization.id).length} projects</option>`).join('')}</select></label><span class="project-selection-count" data-project-selection-count>${administrator?'All projects':`${user.projectIds?.length||0} directly selected`}</span></div><div class="permission-grid project-permissions">${projects().map(project=>{const organization=orgs().find(item=>item.id===project.organizationId),inherited=!administrator&&user.organizationIds?.includes(project.organizationId);return `<label class="checkline" data-project-organization="${escape(project.organizationId)}" ${project.organizationId===initialOrganizationId?'':'hidden'}><input type="checkbox" name="projectIds" value="${project.id}" ${administrator||user.projectIds?.includes(project.id)?'checked':''} ${administrator?'disabled':''}><span><strong>${escape(project.projectNo||'')}</strong>${project.projectNo?' · ':''}${escape(project.name)} <small>${inherited?'Inherited from organization':'Direct access'}</small></span></label>`}).join('')}</div><p class="small project-filter-empty" data-project-filter-empty hidden>No projects are available in this organization.</p>`:'<p class="small">No projects are available yet. Project managers receive direct access to projects they create.</p>'}</fieldset>`; }
function agentAccessFields(user={}) { const administrator=user.role==='administrator';return `<fieldset class="access-fieldset"><legend>Agent access</legend>${administrator?'<div class="notice compact-notice">All current and future agents</div>':''}<p class="small">Choose multiple specialists this user may talk to inside their permitted projects.</p><div class="permission-grid agent-permissions">${experts().map(expert=>`<label class="checkline"><input type="checkbox" name="agentIds" value="${expert.id}" ${administrator||user.agentIds?.includes(expert.id)?'checked':''} ${administrator?'disabled':''}><span>${escape(expert.name)} <small>${escape(expert.specialty)}</small></span></label>`).join('')}</div></fieldset>`; }
function roleFields(user={role:'custom',roleName:'Project Member'}) { return `<div class="access-basics"><label class="field">Access level<select name="role"><option value="custom" ${user.role!=='administrator'?'selected':''}>Custom role</option><option value="administrator" ${user.role==='administrator'?'selected':''}>Administrator</option></select></label><label class="field">Role name<input name="roleName" value="${escape(user.roleName || 'Project Member')}" maxlength="60" required></label></div>${permissionFields(user)}${organizationAccessFields(user)}${projectAccessFields(user)}${agentAccessFields(user)}`; }
function userControlV2() { const isAdmin=state.session?.user?.role==='administrator';const current=state.session?.user||{};const account=`<section class="form-card"><div class="section-kicker">Your account</div><h2>Change password</h2><p class="subtle">Use 8 or more characters with uppercase, lowercase and a number. Other sessions will be signed out.</p><form id="password-form" class="form"><label class="field">Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label class="field">New password<input name="newPassword" type="password" minlength="8" autocomplete="new-password" required></label><label class="field">Confirm new password<input name="confirmPassword" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary">Update my password</button></form></section>`;const create=isAdmin?`<section class="form-card"><div class="section-kicker">Administrator tools</div><h2>Add user</h2><p class="subtle">Create a user, name their role, then grant only the permissions, organizations, projects and agents they need.</p><form id="user-create-form" class="form"><div class="access-basics"><label class="field">Full name<input name="name" autocomplete="name" required></label><label class="field">Email<input name="email" type="email" autocomplete="email" placeholder="name@company.com" required></label></div><label class="field">Temporary password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><p class="small">At least 8 characters, including uppercase, lowercase and a number.</p>${roleFields()}<button class="primary">Create user</button></form></section>`:`<section class="form-card"><div class="section-kicker">Your access</div><h2>${escape(current.roleName || 'Custom role')}</h2><p class="subtle">${escape(current.email || '')}</p><div class="tags">${(current.permissions||[]).map(id=>tag(permissionOptions.find(option=>option[0]===id)?.[1]||id)).join('')||tag('No management permissions')}</div><p class="small section">Organization access: ${current.organizationIds?.length?current.organizationIds.map(id=>escape(orgs().find(organization=>organization.id===id)?.name||id)).join(', '):'No assigned organizations'}</p><p class="small">Direct project access: ${current.projectIds?.length?current.projectIds.map(id=>escape(projects().find(project=>project.id===id)?.name||id)).join(', '):'No directly assigned projects'}</p></section>`;const directory=isAdmin?`<section class="form-card section compact-directory"><div class="section-kicker">Access directory</div><h2>Manage users</h2><p class="subtle">Open a user to edit their role, permissions, organization and direct project access, or password.</p><div class="user-list compact-user-list">${(state.data.users||[]).map(user=>`<details class="user-disclosure"><summary><span class="user-summary-main"><strong>${escape(user.name)}</strong><span>${escape(user.email)}</span></span><span class="role-chip">${escape(user.roleName||user.role)}</span><span class="status-pill ${user.status==='disabled'?'simulated':''}">${escape(user.status)}</span><span class="detail-cue">Details</span></summary><div class="user-detail"><form class="form" data-user-form="${user.id}"><div class="access-basics"><label class="field">Name<input name="name" value="${escape(user.name)}" autocomplete="off" required></label><label class="field">Email<input name="email" type="email" value="${escape(user.email)}" autocomplete="off" required></label><label class="field">Status<select name="status"><option value="active" ${user.status==='active'?'selected':''}>Active</option><option value="disabled" ${user.status==='disabled'?'selected':''}>Disabled</option></select></label></div>${roleFields(user)}<div class="detail-actions"><span class="user-meta">${user.lastLoginAt?`Last sign-in ${new Date(user.lastLoginAt).toLocaleString()}`:'Has not signed in yet'}</span><button class="primary">Save access</button></div></form><form class="reset-password-form" data-reset-user="${user.id}"><label class="field">New temporary password<input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="8+ characters" required></label><button class="quiet">Reset password</button></form></div></details>`).join('')}</div></section>`:'';return shell(`${header('User Control','Configure secure roles, granular permissions and organization-level access.')}<div class="split user-control-top">${account}${create}</div>${directory}`); }
const modelCapabilityMeta={chat:['Chat & Reasoning','Agent Chat, WhatsApp replies and assistants.'],speech:['Speech','WhatsApp voice-note transcription.'],vision:['Vision','Image and drawing interpretation.'],image:['Image Generation','Generated illustrations and visual reports.'],embeddings:['Embeddings','Project-document semantic retrieval.'],fallback:['Fallback Chat','Used automatically when the primary chat model is unavailable.']};
function bindModelSettings(){document.querySelectorAll('[data-model-tab]').forEach(button=>button.addEventListener('click',()=>{state.modelSettingsTab=button.dataset.modelTab;render()}));const form=document.querySelector('#capability-model-form');form?.addEventListener('submit',async event=>{event.preventDefault();try{const capability=form.dataset.capability,data=formData(form);data.enabled=form.elements.enabled.checked;await api(`/api/settings/models/${capability}`,{method:'PUT',body:data});await reload(`${modelCapabilityMeta[capability][0]} model settings saved.`)}catch(error){toast(error.message)}});document.querySelector('[data-test-capability-model]')?.addEventListener('click',async event=>{event.currentTarget.disabled=true;try{const result=await api(`/api/settings/models/${event.currentTarget.dataset.testCapabilityModel}/test`,{method:'POST'});toast(result.message)}catch(error){toast(error.message)}finally{event.currentTarget.disabled=false}})}
function connectorRemoteListing(){const payload=state.connectorRemote;if(state.connectorRemoteLoading)return `<section class="form-card section cloud-source-browser"><div class="cloud-browser-loading">Retrieving the project source listing…</div></section>`;if(!payload)return '';const connector=payload.connector||{},items=payload.items||[],crumbs=state.connectorRemoteStack||[];return `<section class="form-card section cloud-source-browser"><header><div><div class="section-kicker">Connected source browser</div><h2>${escape(connector.label||connector.service)}</h2><p>${escape(connector.service)} · live metadata retrieved through this project’s encrypted connection</p></div><div class="cloud-browser-actions">${crumbs.length?'<button class="quiet" data-cloud-back>Back</button>':''}<button class="quiet" data-refresh-cloud="${escape(connector.id)}">Refresh</button></div></header><nav class="cloud-breadcrumbs"><button data-cloud-root="${escape(connector.id)}">Root</button>${crumbs.map((crumb,index)=>`<span>›</span><button data-cloud-crumb="${index}">${escape(crumb.name)}</button>`).join('')}</nav><div class="cloud-list"><div class="cloud-list-head"><span>Name</span><span>Type</span><span>Modified</span><span></span></div>${items.map(item=>`<article><button class="cloud-item-name" ${item.kind==='folder'?`data-cloud-folder="${escape(item.id)}" data-cloud-folder-name="${escape(item.name)}"`:'disabled'}><i>${item.kind==='folder'?'▰':item.kind==='email'?'✉':'▤'}</i><span><strong>${escape(item.name)}</strong><small>${escape(item.detail||item.mimeType||'')}</small></span></button><span>${escape(item.kind)}</span><span>${item.modifiedAt?escape(new Date(item.modifiedAt).toLocaleString()):'—'}</span><span>${item.webUrl?`<a class="quiet" href="${escape(item.webUrl)}" target="_blank" rel="noreferrer">Open source</a>`:''}</span></article>`).join('')||'<p class="connector-empty">This location contains no visible items.</p>'}</div></section>`}
function projectConnectorConfiguration(){
  const projectId=state.projectFilesProjectId||projects()[0]?.id||null,project=projects().find(item=>item.id===projectId),service=connectorCatalog[state.connectorService]?state.connectorService:'OneDrive',guide=connectorGuides[service],catalog=connectorCatalog[service];
  state.connectorService=service;if(state.connectorProjectId!==projectId){state.connectorProjectId=projectId;state.connectorEditingId=null;state.projectConnectors=[];state.connectorConnectionsLoadedFor=null;state.connectorConnectionsError='';state.connectorRemote=null;state.connectorRemoteStack=[]}
  if(!project)return `<section class="form-card section project-connectors-section"><div class="section-kicker">Project sources</div><h2>Cloud, network storage and project email</h2><p class="empty">Create a protected project before configuring its sources.</p></section>`;
  const editing=state.projectConnectors.find(item=>item.id===state.connectorEditingId&&item.service===service)||null;
  const serviceOptions=[...new Set(Object.values(connectorCatalog).map(item=>item.group))].map(group=>`<optgroup label="${escape(group)}">${Object.entries(connectorCatalog).filter(([,item])=>item.group===group).map(([name,item])=>`<option value="${escape(name)}" ${name===service?'selected':''}>${escape(name)} · ${escape(item.kind)}</option>`).join('')}</optgroup>`).join('');
  const fields=catalog.fields.map(([name,label,placeholder])=>`<label class="field">${escape(label)}<input name="${escape(name)}" value="${escape(editing?.config?.[name]||'')}" placeholder="${escape(placeholder)}"></label>`).join('');
  const credentialField=catalog.credentialRequired?`<label class="field">${escape(guide[0])}<input name="credential" type="password" autocomplete="new-password" placeholder="${editing?'Paste a newly authorized access token':'Paste the access_token value'}" required><span>Paste only the OAuth access_token value. Client secrets, authorization codes and account passwords are rejected before saving.</span></label>`:`<div class="notice compact-notice"><strong>No source password stored:</strong> authentication remains with the host mount. Agent Platform receives read-only file access inside the approved source root.</div>`;
  const connections=state.connectorConnectionsLoading?'<p class="connector-empty">Loading protected connection records…</p>':state.connectorConnectionsError?`<div class="notice connector-error"><strong>Connections could not be loaded</strong><br>${escape(state.connectorConnectionsError)}</div>`:state.projectConnectors.length?state.projectConnectors.map(connection=>{const access=connection.authMode==='mounted-readonly'?'Read-only mounted folder · no source password stored':'OAuth credential encrypted and redacted';return `<article class="project-connector-row"><div><span class="connector-service-label">${escape(connection.service)}</span><h3>${escape(connection.label||connection.service)}</h3><p>${access}${connection.testedAt?` · tested ${escape(new Date(connection.testedAt).toLocaleString())}`:''}${connection.lastError?`<br><span class="connector-last-error">${escape(connection.lastError)}</span>`:''}</p></div><div><span class="status-pill ${connection.status==='connected'?'':'simulated'}">${escape(connection.status||'saved')}</span><button type="button" class="primary" data-browse-project-connector="${escape(connection.id)}">Browse source</button><button type="button" class="ghost" data-test-project-connector="${escape(connection.id)}">Test</button><button type="button" class="ghost" data-reconnect-project-connector="${escape(connection.id)}">Reconnect</button><button type="button" class="danger" data-delete-project-connector="${escape(connection.id)}">Disconnect</button></div></article>`}).join(''):'<p class="connector-empty">No cloud, network-drive or project-email source has been saved for this project.</p>';
  return `<section class="project-connectors-section"><div class="connector-option-strip" aria-label="Available connection methods"><span><strong>Cloud accounts</strong><small>OAuth and provider APIs</small></span><span><strong>Project systems</strong><small>Autodesk project data</small></span><span><strong>Network storage</strong><small>SMB, NFS, NAS or host folder</small></span><span><strong>Project email</strong><small>Microsoft Graph mailbox</small></span></div><div class="split project-connector-grid"><section class="form-card"><div class="section-kicker">${escape(catalog.group)}</div><h2>${editing?'Reconnect project source':'Add project source'}</h2>${editing?'<div class="notice compact-notice"><strong>Replace the saved credential:</strong> existing access remains unavailable until a new connection is saved and tested.</div>':''}<form id="project-connector-form" class="form"><input type="hidden" name="projectId" value="${escape(project.id)}"><input type="hidden" name="connectorId" value="${escape(editing?.id||'')}"><label class="field">Source type<select name="service" id="project-connector-service" ${editing?'disabled':''}>${serviceOptions}</select>${editing?`<input type="hidden" name="service" value="${escape(service)}">`:''}</label><label class="field">Connection name<input name="label" value="${escape(editing?.label||'')}" placeholder="e.g. ${escape(project.name)} ${escape(service)}"></label>${fields}<div class="connector-recommendation"><div class="section-kicker">Recommended connection</div><h3>${escape(catalog.method)}</h3><p>${escape(guide[1])}</p><div><strong>${service==='Network Drive'?'Access boundary':'Least-privilege scope'}</strong><code>${escape(catalog.scope)}</code></div><ol>${catalog.steps.map(step=>`<li>${escape(step)}</li>`).join('')}</ol><a href="${escape(guide[2])}" target="_blank" rel="noreferrer">Open official setup guide ↗</a></div>${credentialField}<div class="connector-form-actions">${editing?'<button type="button" class="quiet" data-cancel-connector-reconnect>Cancel</button>':''}<button class="primary">${editing?'Save and reconnect':'Save project connection'}</button></div></form></section><section class="form-card saved-connectors-card"><div><h2>Connected sources</h2><p class="subtle">They appear here like Project Library roots after a successful connection test.</p></div><div id="project-connector-list" class="project-connector-list">${connections}</div></section></div>${connectorRemoteListing()}</section>`;
}
async function loadProjectConnectors(projectId){
  if(!projectId||state.connectorConnectionsLoading)return;state.connectorConnectionsLoading=true;state.connectorConnectionsLoadedFor=projectId;state.connectorConnectionsError='';render();
  try{state.projectConnectors=await api(`/api/projects/${projectId}/connectors`)}catch(error){state.projectConnectors=[];state.connectorConnectionsError=error.message}finally{state.connectorConnectionsLoading=false;if(state.page==='Project Files'&&state.projectFilesTab==='connectors'&&state.connectorProjectId===projectId)render()}
}
async function loadConnectorRemote(connectorId,parentId='',pushCrumb=null){if(!state.connectorProjectId)return;state.connectorRemoteLoading=true;if(pushCrumb)state.connectorRemoteStack.push(pushCrumb);render();try{state.connectorRemote=await api(`/api/projects/${state.connectorProjectId}/connectors/${connectorId}/items${parentId?`?parentId=${encodeURIComponent(parentId)}`:''}`)}catch(error){if(pushCrumb)state.connectorRemoteStack.pop();toast(error.message)}finally{state.connectorRemoteLoading=false;render()}}
function bindProjectConnectorSettings(){
  if(state.page!=='Project Files'||state.projectFilesTab!=='connectors')return;
  document.querySelector('#project-connector-service')?.addEventListener('change',event=>{state.connectorEditingId=null;state.connectorService=event.target.value;render()});
  document.querySelector('#project-connector-form')?.addEventListener('submit',async event=>{event.preventDefault();const data=formData(event.currentTarget),button=event.currentTarget.querySelector('button[type="submit"],button:not([type])'),editingId=data.connectorId||'';if(button)button.disabled=true;try{const connection=await api(`/api/projects/${data.projectId}/connectors${editingId?`/${editingId}`:''}`,{method:editingId?'PUT':'POST',body:data});state.connectorProjectId=data.projectId;state.connectorEditingId=null;state.connectorConnectionsLoadedFor=data.projectId;state.projectConnectors=[...state.projectConnectors.filter(item=>item.id!==connection.id),connection];toast(editingId?'Project source reconnected. Test it before browsing.':'Protected project connection saved. Test it before browsing.');render()}catch(error){toast(error.message);if(button)button.disabled=false}});
  document.querySelectorAll('[data-reconnect-project-connector]').forEach(button=>button.addEventListener('click',()=>{const connection=state.projectConnectors.find(item=>item.id===button.dataset.reconnectProjectConnector);if(!connection)return;state.connectorEditingId=connection.id;state.connectorService=connection.service;state.connectorRemote=null;state.connectorRemoteStack=[];render();requestAnimationFrame(()=>document.querySelector('#project-connector-form')?.scrollIntoView({behavior:'smooth',block:'start'}))}));
  document.querySelector('[data-cancel-connector-reconnect]')?.addEventListener('click',()=>{state.connectorEditingId=null;render()});
  document.querySelectorAll('[data-test-project-connector]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{const result=await api(`/api/projects/${state.connectorProjectId}/connectors/${button.dataset.testProjectConnector}/test`,{method:'POST'});state.projectConnectors=state.projectConnectors.map(item=>item.id===result.id?result:item);toast(result.result||'Connection test completed.');render()}catch(error){toast(error.message);button.disabled=false}}));
  document.querySelectorAll('[data-browse-project-connector]').forEach(button=>button.addEventListener('click',()=>{state.connectorRemoteStack=[];loadConnectorRemote(button.dataset.browseProjectConnector)}));
  document.querySelectorAll('[data-delete-project-connector]').forEach(button=>button.addEventListener('click',async()=>{if(!await askConfirmation('This project source will be disconnected and its encrypted credential deleted. Local Project Library files are not affected.',{title:'Disconnect project source?',confirmLabel:'Disconnect',tone:'danger'}))return;try{await api(`/api/projects/${state.connectorProjectId}/connectors/${button.dataset.deleteProjectConnector}`,{method:'DELETE'});state.connectorRemote=null;state.connectorRemoteStack=[];state.connectorConnectionsLoadedFor=null;await loadProjectConnectors(state.connectorProjectId);toast('Project source disconnected.')}catch(error){toast(error.message)}}));
  document.querySelectorAll('[data-cloud-folder]').forEach(button=>button.addEventListener('click',()=>loadConnectorRemote(state.connectorRemote.connector.id,button.dataset.cloudFolder,{id:button.dataset.cloudFolder,name:button.dataset.cloudFolderName})));
  document.querySelector('[data-cloud-back]')?.addEventListener('click',()=>{state.connectorRemoteStack.pop();const previous=state.connectorRemoteStack.at(-1);loadConnectorRemote(state.connectorRemote.connector.id,previous?.id||'')});
  document.querySelectorAll('[data-cloud-root]').forEach(button=>button.addEventListener('click',()=>{state.connectorRemoteStack=[];loadConnectorRemote(button.dataset.cloudRoot)}));
  document.querySelectorAll('[data-cloud-crumb]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.cloudCrumb),target=state.connectorRemoteStack[index];state.connectorRemoteStack=state.connectorRemoteStack.slice(0,index+1);loadConnectorRemote(state.connectorRemote.connector.id,target?.id||'')}));
  document.querySelectorAll('[data-refresh-cloud]').forEach(button=>button.addEventListener('click',()=>loadConnectorRemote(button.dataset.refreshCloud,state.connectorRemote?.parentId||'')));
  if(state.connectorProjectId&&state.connectorConnectionsLoadedFor!==state.connectorProjectId&&!state.connectorConnectionsLoading)loadProjectConnectors(state.connectorProjectId);
}
