  return `<section class="translation-settings"><header class="form-card translation-toolbar"><div><div class="section-kicker">Translation settings</div><h2>Review and correct interface text</h2><p class="subtle">Built-in translations remain as the fallback. An approved override takes effect for every user of that language and can be cleared at any time.</p></div><div class="translation-controls"><label class="field">Language<select id="translation-editor-language"><option value="zh-Hant" ${language==='zh-Hant'?'selected':''}>Traditional Chinese</option><option value="zh-Hans" ${language==='zh-Hans'?'selected':''}>Simplified Chinese</option></select></label><form id="translation-search-form" class="translation-search"><label class="field">Search English source text<input name="search" value="${escape(state.translationSearch)}" placeholder="e.g. Project Files"></label><button class="ghost">Search</button>${state.translationSearch?'<button type="button" class="quiet" data-clear-translation-search>Clear</button>':''}</form></div></header><div class="translation-summary"><span><strong>${entries.length}</strong> visible phrases</span><span><strong>${Object.keys(overrides).length}</strong> custom overrides</span></div><details class="form-card translation-add"><summary>Add a missing phrase</summary><p class="subtle">Copy the exact English interface text, then provide the approved translation. Exact matching keeps project names and user content untouched.</p><form id="translation-add-form"><label class="field">English source<input name="source" maxlength="500" required></label><label class="field">Approved override<textarea name="translation" maxlength="2000" required></textarea></label><button class="primary">Add translation</button></form></details><div class="translation-list">${entries.map(source=>{const builtIn=translations[language]?.[source]||'',override=overrides[source]||'';return `<form class="translation-row ${override?'overridden':''}" data-translation-source="${escape(source)}"><div class="translation-source"><span>English source</span><strong data-no-localize>${escape(source)}</strong></div><div class="translation-built-in"><span>Built-in translation</span><p data-no-localize>${escape(builtIn||'No built-in translation')}</p></div><label><span>Approved override</span><textarea data-no-localize name="translation" maxlength="2000" placeholder="${escape(builtIn||'Enter approved translation')}">${escape(override)}</textarea></label><div class="translation-row-actions"><span class="translation-state">${override?'Custom override':'Built-in'}</span><button class="primary">Save translation</button>${override?'<button type="button" class="danger" data-clear-translation>Clear override</button>':''}</div></form>`}).join('')||'<p class="form-card empty">No translation entries match this search.</p>'}</div></section>`;
